  "prediction_basis_card_ids": ["C55","C56","C57","C58","C62","C64","C72","C74","C65","C75","C73","C69"],
  "claims": [
    {
      "claim": "L4 solubility records for structurally related large lipophilic drugs show very low fasted-state solubility/dissolution: atazanavir is <1 µg/mL at pH ≥4 with crystalline solubility ~0.8–1.46 µg/mL in bile-salt media and pure-drug dissolution of only 30.56%; the pibrentasvir parent is <0.1 mg/mL at pH 7.4.",
      "card_ids": ["C55","C56","C57","C58","C62","C64"]
    },
    {
      "claim": "L5 records identify pibrentasvir, a structurally related bivalent NS5A inhibitor, as a P-gp/BCRP substrate with intestinal efflux implicated in its oral bioavailability; ledipasvir, velpatasvir, and ombitasvir are also P-gp substrates, and P-gp-mediated intestinal efflux is reported to reduce oral bioavailability for velpatasvir.",
      "card_ids": ["C72","C74","C73","C75","C69"]
    },
    {
      "claim": "The query's physicochemical profile (MW 738.9, logP 6.22, TPSA 174.6, 4 HBD/8 HBA) is unfavorable for fasted-state absorption and is consistent with the solubility and efflux liabilities observed for related chemotypes.",
      "card_ids": ["C55","C62","C72"]
    },
    {
      "claim": "L1 high-F contexts (alpelisib, encorafenib, acalabrutinib, etc.) involve smaller, less polar molecules and are not sufficiently transferable to the query's large bivalent scaffold; they do not provide affirmative evidence for F ≥ 20%.",
      "card_ids": ["C01","C03","C19","C20"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C72","C74","C65","C75","C73","C69"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or PK measurement exists for the query molecule.",
    "No query-specific solubility, permeability (Caco-2/PAMPA), or efflux assay data are available; L4/L5 records are for analogs (atazanavir, pibrentasvir, ledipasvir, velpatasvir, ombitasvir).",
    "No first-pass metabolism or clearance data are available for the query.",
    "No formulation or dose information is provided; the fasted state may further limit dissolution.",
    "Transferability of L1 high-F contexts is limited by the query's larger size and higher polarity.",
    "P-gp substrate status alone does not establish F < 20%; it is used only as mechanistic support."
  ],
  "decision_summary": "Prediction remains low: L4 solubility records for related large lipophilic drugs and L5 P-gp/BCRP efflux evidence for structurally related NS5A inhibitors coherently support fasted-state absorption limitation, while L1 high-F contexts are not transferable to the query's large bivalent scaffold. Confidence is low because no direct F or query-specific permeability data exist."
}

